const modal=document.querySelector('#demo'),content=document.querySelector('#demo-content');
const dishes=[{name:'Tomates de temporada',category:'Entrantes',description:'Tomate, aceite de oliva y hierbas frescas.',price:'9 €'},{name:'Queso asado',category:'Entrantes',description:'Queso a la plancha con mojo verde.',price:'11 €'},{name:'Arroz de la huerta',category:'Principales',description:'Arroz meloso con verduras de temporada.',price:'16 €'},{name:'Pescado del día',category:'Principales',description:'Con papas y ensalada fresca.',price:'21 €'},{name:'Mousse de gofio',category:'Postres',description:'Un final suave con sabor a las islas.',price:'6 €'}];
function restaurant(){content.innerHTML='<h2 class="demo-head">Brasa & Sal</h2><p class="demo-sub">Una carta que se entiende de un vistazo. Precios ilustrativos.</p><div class="tabs" role="group" aria-label="Categorías de la carta"></div><div id="dishes" aria-live="polite"></div><p class="warning">Ejemplo de carta digital. En una web real se añadirían los alérgenos y la información validada por el restaurante.</p>';const tabs=content.querySelector('.tabs');['Todos','Entrantes','Principales','Postres'].forEach(category=>{const b=document.createElement('button');b.textContent=category;b.type='button';b.setAttribute('aria-pressed',category==='Todos');b.onclick=()=>{tabs.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));render(category)};tabs.append(b)});function render(c){content.querySelector('#dishes').innerHTML=dishes.filter(d=>c==='Todos'||d.category===c).map(d=>`<div class="dish"><div><h3>${d.name}</h3><p>${d.description}</p></div><strong>${d.price}</strong></div>`).join('')}render('Todos')}
function salon(){content.innerHTML='<h2 class="demo-head">Nativa · Tu próxima cita</h2><p class="demo-sub">Prueba el recorrido de una reserva. No se registra ninguna cita real.</p><form id="booking"><label>Servicio<select name="service"><option>Corte y acabado · 45 min</option><option>Color y cuidado · 90 min</option><option>Tratamiento capilar · 30 min</option></select></label><label>Fecha<input type="date" name="date" required></label><label>Hora orientativa<select name="time"><option>10:00</option><option>11:30</option><option>16:00</option><option>17:30</option></select></label><button class="button">Simular reserva ↗</button></form><div id="booking-result" role="status"></div><p class="warning">Horarios ficticios. La disponibilidad real, las confirmaciones y los recordatorios requieren conectar una agenda.</p>';const form=content.querySelector('form');const now=new Date();const date=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');form.elements.date.min=date;form.elements.date.value=date;form.onsubmit=e=>{e.preventDefault();const result=content.querySelector('#booking-result');result.className='result';result.textContent=`Simulación completada: ${form.elements.service.value}, el ${new Date(form.elements.date.value+'T12:00:00').toLocaleDateString('es-ES')}, a las ${form.elements.time.value}. No se ha enviado ni reservado ninguna cita.`}}
function services(){content.innerHTML='<h2 class="demo-head">Trazo · Cuéntanos tu idea</h2><p class="demo-sub">Un formulario breve para orientar la primera conversación.</p><form id="request"><label>Tipo de proyecto<select name="type"><option>Reforma de cocina</option><option>Reforma de baño</option><option>Reforma integral</option><option>Renovación de local</option></select></label><label>Superficie aproximada (m²)<input name="area" type="number" min="1" max="10000" required placeholder="Ej. 45"></label><label>Cuándo te gustaría empezar<select name="when"><option>En cuanto sea posible</option><option>En los próximos 3 meses</option><option>Estoy explorando opciones</option></select></label><button class="button">Ver solicitud ↗</button></form><div id="request-result" role="status"></div><p class="warning">Demostración sin envío. El presupuesto real necesita valorar alcance, materiales y condiciones del espacio.</p>';const form=content.querySelector('form');form.onsubmit=e=>{e.preventDefault();const r=content.querySelector('#request-result');r.className='result';r.textContent=`Resumen: ${form.elements.type.value} · ${form.elements.area.value} m² · ${form.elements.when.value}. Con estos datos, el profesional podría preparar las preguntas para una primera visita.`}}
modal.setAttribute('aria-label','Demostración de funcionalidades web');document.querySelectorAll('[data-demo]').forEach(b=>b.addEventListener('click',()=>{({restaurant,salon,services})[b.dataset.demo]();modal.showModal()}));document.querySelector('#close').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
document.querySelector('#brief').onsubmit=e=>{e.preventDefault();const f=e.target;document.querySelector('#brief-text').textContent=`MI PROYECTO WEB\n\nNegocio: ${f.elements.sector.value}\nSituación: ${f.elements.situation.value}\nObjetivo: ${f.elements.goal.value.trim()}\n\nPor definir: contenidos, funciones, plazo, presupuesto, dominio y mantenimiento.`;const r=document.querySelector('#brief-result');r.hidden=false;document.querySelector('#copy-status').textContent='';r.scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})};document.querySelector('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(document.querySelector('#brief-text').textContent);document.querySelector('#copy-status').textContent='Resumen copiado.'}catch{document.querySelector('#copy-status').textContent='Selecciona el resumen para copiarlo manualmente.'}};
